class Solution {
  public boolean isInterleave(String s1, String s2, String s3) {
    int n = s1.length(), m = s2.length(), t = s3.length();

    if (n + m != t) {
      return false;
    }

    boolean[][] f = new boolean[n + 1][m + 1];

    f[0][0] = true;
    for (int i = 0; i <= n; ++i) {
      for (int j = 0; j <= m; ++j) {
        int p = i + j - 1;
        if (i > 0) {
          f[i][j] = f[i][j] || (f[i - 1][j] && s1.charAt(i - 1) == s3.charAt(p));
        }
        if (j > 0) {
          f[i][j] = f[i][j] || (f[i][j - 1] && s2.charAt(j - 1) == s3.charAt(p));
        }
      }
    }

    return f[n][m];
  }
}

class Solution:
    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        n, m = len(s1), len(s2)
        if n + m != len(s3):
            return False
        f = [[False] * (m + 1) for _ in range(n + 1)]
        f[0][0] = True
        for i in range(n + 1):
            for j in range(m + 1):
                p = i + j - 1
                if i > 0:
                    f[i][j] = f[i][j] or (f[i - 1][j] and s1[i - 1] == s3[p])
                if j > 0:
                    f[i][j] = f[i][j] or (f[i][j - 1] and s2[j - 1] == s3[p])
        return f[n][m]

impl Solution {
  pub fn is_interleave(s1: String, s2: String, s3: String) -> bool {
    let (a, b, c) = (s1.as_bytes(), s2.as_bytes(), s3.as_bytes());
    let (n, m) = (a.len(), b.len());
    if n + m != c.len() {
      return false;
    }
    let mut f = vec![vec![false; m + 1]; n + 1];
    f[0][0] = true;
    for i in 0..=n {
      for j in 0..=m {
        let p = i + j;
        if i > 0 {
          f[i][j] = f[i][j] || (f[i - 1][j] && a[i - 1] == c[p - 1]);
        }
        if j > 0 {
          f[i][j] = f[i][j] || (f[i][j - 1] && b[j - 1] == c[p - 1]);
        }
      }
    }
    f[n][m]
  }
}

